using System.Collections;
using LittleLeo;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "BringBackAction", menuName = "Data/Battle/Battle Actions/Orion/BringBack Action")]
public class BringBackAction : SearchDiceOnPoolAction
{
	[Header("BringBackAction Specifics")]
	[SerializeField]
	private PlayerDiceInventoryData playerDicePool;

	[SerializeField]
	private TransformReference discardPoolButtonTransformReference;

	[Header("Receive Dice Animation")]
	[SerializeField]
	private GameObject receiveDiceAnimationPrefab;

	public override void DiceChosen(Dice dice)
	{
		OnHideSearchDiceOnPoolCanvas.Raise();
		ReferenceSingleton<CoroutineHandler>.Instance.Run(SendDiceToBagAnimation(dice));
	}

	private IEnumerator SendDiceToBagAnimation(Dice dice)
	{
		ReceiveDiceAnimation component = ReferenceSingleton<PoolHandler>.Instance.GetObject(receiveDiceAnimationPrefab.name, discardPoolButtonTransformReference.value.position).GetComponent<ReceiveDiceAnimation>();
		playerDicePool.IncreaseDiceAmount(dice, 1, insertAsFirst: false, updateDicePoolText: false);
		component.Initialize(BagEnum.DrawPool, dice, playerDicePool);
		component.StartAnimation();
		poolToChooseFrom.DecreaseDiceAmount(dice, 1);
		yield return new WaitForSeconds(0.65f);
		ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
	}
}
